from gklib import L, S, Q
L("space","how-big-is-the-solar-system","5-7","Our Solar System","Meet the Sun and its eight planets, and see how they travel around it.","🪐",[
 S("The Sun is our star","The Sun is a giant ball of hot, glowing gas. | It is a star, just like the tiny lights you see at night. | The Sun gives us light and warmth, and everything in our Solar System travels around it.",["The Sun is a star","It gives light and heat","Planets travel around it"],"solar-system"),
 S("Eight planets","There are eight planets that go around the Sun. | In order from the Sun they are Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus and Neptune. | The path a planet takes around the Sun is called its orbit.",["Mercury, Venus, Earth, Mars","Jupiter, Saturn, Uranus, Neptune","A planet's path is an orbit"],"solar-system"),
 S("Small and big","The four planets nearest the Sun are small and rocky, and Earth is one of them. | The four planets farther away are huge and are made mostly of gas and ice. | Jupiter is the biggest planet of all.",["Near the Sun: small and rocky","Far from the Sun: huge and gassy","Jupiter is the biggest"]),
 S("A year is a trip","One trip around the Sun is called a year. | Earth takes about 365 days to make one trip. | Mercury is close to the Sun, so it finishes a trip in only 88 days, but Neptune takes about 165 Earth years.",["Earth: about 365 days","Mercury: 88 days","Neptune: about 165 years"]),
],facts=["If the Sun were a large front door, Earth would be about the size of a coin.","Saturn is so light for its size that, on average, it is less dense than water.","A day on Venus is longer than its year."],
quiz=[Q("Which planet is the biggest?",["Earth","Jupiter","Mars"],1,"Jupiter is the biggest planet, more than 1,000 Earths could fit inside it."),
Q("What do we call the path a planet takes around the Sun?",["A road","An orbit","A line"],1,"The curved path of a planet around the Sun is called its orbit."),
Q("How many planets are in our Solar System?",["Six","Eight","Ten"],1,"There are eight planets: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus and Neptune.")],tags=["planets","sun","orbit"],notes="The IAU defined 'planet' in 2006, which is why Pluto is now called a dwarf planet.")

L("space","why-moon-changes-shape","8-10","Why Does the Moon Change Shape?","The Moon does not really change. Find out why we see a thin curve one night and a full circle later.","🌙",[
 S("The Moon makes no light","The Moon does not make its own light. | We see it because sunlight bounces off its surface and reaches our eyes. | Half of the Moon is always lit by the Sun, just like half of Earth is always in daytime.",["The Moon reflects sunlight","Half of it is always lit"],"moon-phases"),
 S("The Moon travels around Earth","The Moon goes around Earth once in about 29 and a half days. | As it moves, we look at its lit half from a slightly different angle each night. | That changing view is what we call the phases of the Moon.",["One trip takes about 29.5 days","Our view of the lit half changes","These are the phases"],"moon-phases"),
 S("The phases in order","When the Moon is between Earth and the Sun, its lit side faces away from us and we see a new moon. | A few nights later we see a thin crescent, then a half moon, then a full moon when Earth is between the Moon and the Sun. | After the full moon the lit part shrinks again until the next new moon.",["New moon: no lit part seen","Half moon: half the face","Full moon: the whole face"],"moon-phases"),
 S("Waxing and waning","When the lit part is growing, we say the Moon is waxing. | When it is shrinking, we say it is waning. | In India the bright part of a waxing moon is on the right side, and for a waning moon it is on the left.",["Waxing: growing","Waning: shrinking"]),
],facts=["The same side of the Moon always faces Earth, so we never see the far side from here.","The Moon is slowly moving away from Earth, about 3.8 centimetres every year.","A full moon rises around sunset, and a new moon rises around sunrise."],
quiz=[Q("Why can we see the Moon?",["It makes its own light","It reflects sunlight","It has lamps on it"],1,"The Moon only reflects light from the Sun."),
Q("About how long is one full cycle of phases?",["7 days","About 29 and a half days","365 days"],1,"The Moon takes about 29.5 days to go from one new moon to the next."),
Q("When do we see a full moon?",["When Earth is between the Moon and the Sun","When the Moon is between Earth and the Sun","Only in winter"],0,"At full moon, Earth is roughly between the Sun and the Moon, so the whole lit half faces us.")],tags=["moon","phases","orbit"])

L("space","eclipses-shadows-in-space","11-13","Eclipses: Shadows in Space","How the Sun and Moon line up to cast shadows, and why eclipses do not happen every month.","🌘",[
 S("A shadow game","An eclipse happens when one space object moves into the shadow of another. | Earth, the Moon and the Sun are the three players. | There are two kinds that we see from Earth: solar eclipses and lunar eclipses.",["Eclipse = a shadow in space","Three players: Sun, Earth, Moon"],"eclipses"),
 S("Solar eclipse","In a solar eclipse the Moon passes between the Sun and Earth. | The Moon blocks the Sun's light and its shadow falls on a small part of Earth. | The Sun is about 400 times wider than the Moon, but also about 400 times farther away, so the Moon can just cover it.",["Moon is in the middle","The Moon's shadow falls on Earth","Sun and Moon look the same size"],"eclipses"),
 S("Lunar eclipse","In a lunar eclipse, Earth is in the middle, and the Moon moves into Earth's shadow. | The Moon often looks dull red, because some sunlight bends through Earth's air and reaches it. | A lunar eclipse is safe to watch with the eyes, but a solar eclipse is not.",["Earth is in the middle","The Moon looks dull red","Lunar is safe to watch"],"eclipses"),
 S("Why not every month?","The Moon's orbit is tilted about five degrees compared with Earth's orbit around the Sun. | So most months the Moon passes a little above or below the straight line. | An eclipse happens only when the three line up closely enough.",["Moon's orbit is tilted about 5 degrees","Only exact lineups give eclipses"]),
],facts=["Never look directly at the Sun, even during an eclipse, without proper eclipse glasses.","The darkest part of a solar eclipse is called totality and can last up to about seven minutes.","Ancient astronomers learned to predict eclipses by noticing repeating cycles."],
quiz=[Q("In a solar eclipse, which object is in the middle?",["Earth","The Moon","The Sun"],1,"The Moon passes between the Sun and Earth."),
Q("Why do eclipses not happen every month?",["The Moon is too far","The Moon's orbit is tilted","The Sun moves away"],1,"The Moon's orbit is tilted by about 5 degrees, so it usually misses the shadow line."),
Q("Which eclipse is safe to watch with bare eyes?",["Solar","Lunar","Both"],1,"A lunar eclipse only dims reflected light, so it is safe. Looking at the Sun is never safe.")],tags=["eclipse","moon","sun"])

L("space","how-rockets-reach-space","11-13","How Rockets Reach Space","The idea of action and reaction, why rockets have stages and what makes an orbit.","🚀",[
 S("Push back, move forward","A rocket moves by throwing hot gas out of its bottom very fast. | Newton's third law says that for every action there is an equal and opposite reaction. | The gas goes down, so the rocket goes up.",["Hot gas shoots out downward","Action and reaction","The rocket moves up"]),
 S("Why not just go up?","To stay in orbit around Earth, a spacecraft must travel sideways at about 7.8 kilometres every second. | It is still falling toward Earth, but it moves sideways so fast that the ground curves away beneath it. | That endless falling around the planet is an orbit.",["Orbit needs sideways speed","About 7.8 km every second","Falling around Earth"]),
 S("Stages","Rockets carry fuel, and fuel is heavy. | So a rocket is built in stages, and each empty stage is dropped off to make the rest lighter. | India's launch vehicles from ISRO use stages in exactly this way.",["Drop empty stages","Lighter rocket goes faster"]),
 S("Escape","To go all the way to the Moon, a spacecraft needs even more speed so that it can escape Earth's pull. | The speed needed to leave Earth altogether is about 11.2 kilometres every second. | That is called the escape velocity.",["Escape velocity: about 11.2 km/s"]),
],facts=["Astronauts in orbit feel weightless because they are in free fall, not because there is no gravity.","The International Space Station circles Earth about every 90 minutes.","Chandrayaan-3 landed near the Moon's south pole in August 2023."],
quiz=[Q("What makes a rocket move up?",["Pushing against air","Hot gas thrown out downward","Magnets"],1,"A rocket works by action and reaction, gas goes down and the rocket goes up. It works even in empty space."),
Q("Why do rockets drop stages?",["To look good","To become lighter","To change colour"],1,"Dropping empty tanks removes weight, so the rest can speed up more easily."),
Q("An orbit is best described as...",["Floating with no gravity","Falling around Earth while moving sideways fast","Flying like a plane"],1,"The spacecraft keeps falling but moves sideways so fast that it keeps missing the ground.")],tags=["rocket","orbit","isro"],asof="November 2026",notes="Speeds are rounded. Chandrayaan-3 landing on 23 August 2023 is a fixed historical fact.")

L("space","stars-and-galaxies","11-13","Stars and Galaxies","What stars are, how they are born, why they twinkle and how big the Universe is.","✨",[
 S("A star is a Sun","Every star you see at night is a sun, a huge ball of hot gas making its own light. | They look tiny only because they are extremely far away. | After the Sun, the nearest star to us is Proxima Centauri, about 4.2 light-years away.",["Stars make their own light","They are very far away"]),
 S("What is a light-year?","A light-year is a distance, not a time. | It is how far light travels in one year, about nine and a half trillion kilometres. | So when you see a star 100 light-years away, you are seeing light that left it 100 years ago.",["A light-year measures distance","About 9.5 trillion km","Looking far means looking back in time"]),
 S("Birth and death of a star","Stars are born inside clouds of gas and dust that clump together under gravity. | They shine for millions or billions of years by joining tiny atoms together in their cores. | When a star runs out of fuel it changes, and very large stars end in a huge explosion called a supernova.",["Born in gas and dust clouds","Shine by joining atoms","Big stars end as supernovae"]),
 S("Galaxies","A galaxy is a giant family of stars, gas and dust held together by gravity. | Our home is the Milky Way, which has more than a hundred billion stars. | There are billions of other galaxies in the Universe.",["Galaxy = stars held by gravity","We live in the Milky Way"]),
],facts=["Stars twinkle because their light wobbles as it passes through moving layers of Earth's air. Planets usually twinkle less.","The Sun is about 4.6 billion years old.","The Milky Way is so wide that light takes roughly 100,000 years to cross it."],
quiz=[Q("A light-year measures...",["Time","Distance","Brightness"],1,"It is the distance light travels in one year."),
Q("Why do stars look so tiny?",["They are small","They are very far away","They are cold"],1,"Stars are huge, but they are trillions of kilometres away."),
Q("What is the name of our galaxy?",["Andromeda","Milky Way","Orion"],1,"We live in the Milky Way galaxy.")],tags=["stars","galaxy","universe"])
